using System.Collections.Concurrent;
namespace Scheduler.Core;
public sealed class LruCache<TKey,TValue> where TKey:notnull
{private readonly int _capacity;private readonly Dictionary<TKey,LinkedListNode<(TKey Key,TValue Value)>> _index=[];private readonly LinkedList<(TKey Key,TValue Value)> _items=[];public LruCache(int capacity)=>_capacity=capacity>0?capacity:throw new ArgumentOutOfRangeException(nameof(capacity));public bool TryGet(TKey key,out TValue? value){if(!_index.TryGetValue(key,out var node)){value=default;return false;}_items.Remove(node);_items.AddFirst(node);value=node.Value.Value;return true;}public void Put(TKey key,TValue value){if(_index.TryGetValue(key,out var node)){node.Value=(key,value);_items.Remove(node);_items.AddFirst(node);return;}var added=_items.AddFirst((key,value));_index[key]=added;if(_items.Count<=_capacity)return;var last=_items.Last!;_items.RemoveLast();_index.Remove(last.Value.Key);}}
public sealed class BoundedWorkQueue<T>(int capacity):IAsyncDisposable
{private readonly BlockingCollection<T> _queue=new(capacity);public void Add(T item,CancellationToken token=default)=>_queue.Add(item,token);public bool TryTake(out T? item,TimeSpan timeout,CancellationToken token=default)=>_queue.TryTake(out item,(int)timeout.TotalMilliseconds,token);public void Complete()=>_queue.CompleteAdding();public ValueTask DisposeAsync(){_queue.Dispose();return ValueTask.CompletedTask;}}
